// Element data for the chemistry engine, Z = 1 to 103.
// @source S-034 (pymatgen: name, mass, period, group, block, category, Pauling electronegativity, vdW radius)
// @source S-021 via S-052 (Cordero 2008 covalent radii, ASE 3.29.0 transcription; null where Cordero has none)
// @source S-051 (SMACT 4.0.2 ICSD 2024 oxidation-state shares)
// Generated by scripts/data/build_elements.py into src/data/elements.json.
import data from '../../data/elements.json';

export type ElementCategory =
  | 'alkali-metal'
  | 'alkaline-earth-metal'
  | 'transition-metal'
  | 'post-transition-metal'
  | 'lanthanide'
  | 'actinide'
  | 'metalloid'
  | 'nonmetal'
  | 'halogen'
  | 'noble-gas';
export interface ElementData {
  Z: number;
  symbol: string;
  name: string;
  mass: number;
  period: number;
  group: number;
  block: string;
  category: ElementCategory;
  metal: boolean;
  /** Pauling electronegativity, null where the source has none (He, Ne, Ar). */
  pauling: number | null;
  vdw: number | null;
  /** Cordero covalent radius in angstrom, null where Cordero 2008 gives none (Bk to Lr). */
  covalent: number | null;
  /** Share of each non-zero oxidation state among ICSD 2024 entries (SMACT counts). */
  oxShares: Record<string, number>;
}

export const ELEMENTS = data.elements as ElementData[];
export const elementsMeta = data._meta;
const BY_SYMBOL = new Map(ELEMENTS.map((e) => [e.symbol, e]));

export const elementData = (symbol: string): ElementData | undefined => BY_SYMBOL.get(symbol);
export const covalentRadius = (symbol: string): number | null => BY_SYMBOL.get(symbol)?.covalent ?? null;
export const paulingX = (symbol: string): number | null => BY_SYMBOL.get(symbol)?.pauling ?? null;
export const isMetal = (symbol: string): boolean => BY_SYMBOL.get(symbol)?.metal ?? false;
